(function(w,doc){'use strict';var D=w.STORY_DATA,M=w.STORY_MODEL,S,profile='',key='',notes={},memory={},storageOK=true,corrupt=false,view='library',savedId='',showText=false,audio=new Audio(),token=0,toastTimer,db=null,rec=null,recordSaving=false,stream=null,recTimer,recURL='',recRef='',offline=false;var stages=['listen','order','meaning','word','sentence','compose','review'];var showSteps=false,showWriting=false,showAllStories=false,pendingReload=null,ownWorkerAtBoot=!!(navigator.serviceWorker&&navigator.serviceWorker.controller&&navigator.serviceWorker.controller.scriptURL.indexOf('/story-language-lab/sw.js')>=0);
function $(id){return doc.getElementById(id)}function esc(x){return String(x==null?'':x).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}function t(ar,en){return S.language==='ar'?ar:en}
function api(){try{if(w.parent!==w&&w.parent.APP360_FAMILY_SYNC)return w.parent.APP360_FAMILY_SYNC}catch(e){}return w.APP360_FAMILY_SYNC||null}
function identity(){var a=api(),p='';try{p=a&&a.getProfileKey?a.getProfileKey():''}catch(e){}return p&&p!=='name:'?String(p):'local-guest'}
function name(){var a=api();try{if(a&&a.getName&&a.getName())return a.getName()}catch(e){}return t('مستخدم هذا الجهاز','This device learner')}
function coachAllowed(){var a=api(),s;try{s=a&&a.getSession?a.getSession():null}catch(e){}return !(s&&s.room&&s.role==='guest'&&s.adminRole!=='assistant')}
function notify(msg){$('notice').textContent=msg;$('notice').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(function(){$('notice').style.display='none'},4500)}
function storageLabel(){$('storageStatus').textContent=corrupt?t('ملف الحفظ يحتاج استعادة؛ لن نكتب فوقه.','Saved file needs recovery; it will not be overwritten.'):storageOK?t('يحفظ على جهازك','Saved on this device'):t('حفظ مؤقت؛ صدّر حكاياتك قبل الإغلاق','Temporary memory; export before closing')}
function save(){if(!S)return;memory[profile]={state:M.copy(S),notes:M.copy(notes)};if(!corrupt)try{localStorage.setItem(key,JSON.stringify(S));localStorage.setItem(key+':coach',JSON.stringify(notes));storageOK=true}catch(e){storageOK=false}storageLabel()}
function load(p){profile=p;key='app360:a4-story-language:schema-1:'+encodeURIComponent(p);S=M.blank();notes={};corrupt=false;storageOK=true;if(memory[p]){S=M.copy(memory[p].state);notes=M.copy(memory[p].notes)}else try{S=M.restore(localStorage.getItem(key),D);var n=JSON.parse(localStorage.getItem(key+':coach')||'{}');if(n&&typeof n==='object')notes=n}catch(e){if(e.message==='corrupt-storage'||e.message==='unknown-schema')corrupt=true;else storageOK=false}view=S.page;openDB();render()}
function story(){return M.findStory(D,S,S.active)}function draft(){return M.ensureDraft(S,story())}
function stopAudio(){token++;if(w.APP360_STORY_AUDIO)w.APP360_STORY_AUDIO.stop();audio.onended=null;try{audio.pause();audio.currentTime=0}catch(e){}}
function go(p){stopAudio();view=p;S.page=stages.indexOf(p)>=0?p:'library';save();render();$('app').focus();w.scrollTo(0,0);if(p==='library'&&pendingReload&&!rec&&!recordSaving){var reload=pendingReload;pendingReload=null;reload()}}

function icon(kind,muted){return'<svg class="ui-icon" viewBox="0 0 24 24" width="22" height="22" aria-hidden="true" focusable="false" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">'+(kind==='book'?'<path d="M12 5v15M12 5C8 2 4 3 2 4v15c4-2 7-1 10 1 3-2 6-3 10-1V4c-2-1-6-2-10 1Z"/>':'<path d="M3 9h4l5-4v14l-5-4H3Z"/>'+(muted?'<path d="m17 9 5 6m0-6-5 6"/>':'<path d="M16 8a6 6 0 0 1 0 8M19 4a11 11 0 0 1 0 16"/>'))+'</svg>'}
function icons(label){return String(label).replace(/🔊|🔈/g,icon('sound')).replace(/📖/g,icon('book'))}
function b(action,label,v,cls,disabled){return'<button type="button" data-do="'+action+'"'+(v!==undefined?' data-value="'+esc(v)+'"':'')+' class="'+(cls||'')+'"'+(disabled?' disabled':'')+'>'+icons(label)+'</button>'}


function supportName(v){return{together:t('معًا خطوة خطوة','Together'),hint:t('بتلميح بسيط','A small hint'),independent:t('أحاول وحدي','My own try')}[v]||''}








function recordPanel(){var d=draft();return'<section class="recorder '+(rec?'recording':'')+'"><h3>'+t('صوت حكايتي · اختياري','My story voice · optional')+'</h3><p class="local-note">'+t('على هذا الجهاز فقط، حتى 60 ثانية. لا رفع تلقائي؛ التصدير لا يتضمن التسجيل.','On this device only, up to 60 seconds. No upload; excluded from export.')+'</p><div class="row">'+b(rec?'record-stop':'record-start',rec?t('● إنهاء التسجيل','● Finish recording'):t('● سجّل حكايتك','● Record your story'),undefined,rec?'coral':'')+b('record-play',t('▶ اسمع تسجيلك','▶ Hear your recording'),undefined,'small',!(d.recording_ref_optional||recURL))+b('record-delete',t('حذف الصوت','Delete voice'),undefined,'small danger',!(d.recording_ref_optional||recURL))+'</div><p id="recordStatus" class="local-note">'+(rec?t('جارٍ التسجيل…','Recording…'):d.recording_ref_optional?t('يوجد تسجيل محلي.','A local recording is saved.'):'')+'</p></section>'}


function findSaved(id){for(var i=0;i<S.saved.length;i++)if(S.saved[i].id===id)return S.saved[i];return null}
function savedLibrary(){var out='<div class="row spread"><h1>'+t('رفّ حكاياتي','My story shelf')+'</h1>'+b('export',t('تصدير الحكايات','Export stories'),undefined,'small',!S.saved.length)+'</div><p class="export-note">'+t('التصدير يحفظ الحكاية وتعليقاتها، دون الصوت أو الملاحظات الخاصة أو هوية المستخدم.','Export includes stories and captions; no voice recordings, private notes or profile identity.')+'</p><label for="importFile">'+t('استعادة من ملف JSON','Restore from JSON file')+'</label><input id="importFile" type="file" accept="application/json,.json"><section class="panel">';if(!S.saved.length)out+='<div class="empty"><h2>'+t('أول حكاية تنتظرك','Your first story is waiting')+'</h2>'+b('library',t('إلى الحكايات','Explore stories'),undefined,'primary')+'</div>';S.saved.slice().reverse().forEach(function(a){out+='<article class="saved-row"><h3 dir="'+(a.language==='ar'?'rtl':'ltr')+'">'+esc(a.title)+'</h3><div class="mini-scenes">'+a.scenes.map(function(id){return scene(id,a.language)}).join('')+'</div><div class="row">'+b('read-saved',t('افتح الحكاية','Read story'),a.id,'primary')+b('copy-saved',t('أعدّل نسخة','Edit a copy'),a.id)+b('print',t('طباعة','Print'),a.id)+b('delete-saved',t('حذف','Delete'),a.id,'small danger')+'</div></article>'});return out+'</section>'}
function book(a){return'<article class="book-reader" dir="'+(a.language==='ar'?'rtl':'ltr')+'"><h1>'+esc(a.title)+'</h1><div class="timeline">'+a.scenes.map(function(id){return'<div class="scene-card">'+scene(id,a.language)+'<p class="scene-text">'+esc(a.captions[id]||D.scenes[id].text[a.language])+'</p></div>'}).join('')+'</div>'+(a.ending?'<div class="book-ending">'+esc(a.ending)+'</div>':'')+(a.sentence_text?'<p class="book-sentence">'+esc(a.sentence_text)+'</p>':'')+(a.reflection?'<p>'+esc(a.reflection)+'</p>':'')+'<footer>'+t('حكاية من تأليفك · مدرسة العائلة 360','A story made by you · Family School 360')+'</footer></article>'}
function readSaved(){var a=findSaved(savedId);if(!a)return savedLibrary();return'<div class="row">'+b('library',t('▶ حكاية أخرى','▶ Another story'),undefined,'primary')+(S.progress[a.readiness_track].length>=2&&a.readiness_track!=='extend'?b('level-next',t('✦ المستوى التالي','✦ Next level'),undefined,'coral'):'')+b('saved',t('← رف الحكايات','← Story shelf'))+b('listen-saved',t('▶ اسمع الحكاية','▶ Hear the story'),a.id,'primary')+(a.recording_ref_optional?b('play-saved-recording',t('▶ صوتي المحلي','▶ My local voice'),a.id):'')+b('print',t('طباعة','Print'),a.id)+'</div>'+book(a)+'<p class="local-note">'+t('الاستماع يعيد رواية المشاهد الأصلية؛ تعليقاتك ونهايتك تظهر كما ألفتها، وتسجيلك المحلي متاح حين يوجد.','Audio replays the original pictures. Your captions and ending appear as authored; your local voice is available when recorded.')+'</p>'}
function coach(){if(!coachAllowed())return'<section class="panel"><h2>'+t('مكتب المدرب','Coach desk')+'</h2><p>'+t('يدير المكتب مسؤول الجلسة أو مساعده؛ يمكنك متابعة الحكايات.','The session owner or assistant manages this desk; you can continue the stories.')+'</p>'+b('library',t('افتح الحكايات','Open stories'),undefined,'primary')+'</section>';var s=story()||D.stories.filter(function(x){return x.language===S.language})[0],d=M.ensureDraft(S,s),out='<h1>'+t('مكتب المدرب','Coach desk')+'</h1><section class="panel"><label for="learnerAge">'+t('عمر المتعلم · اقتراح المستوى فقط','Learner age · level suggestion only')+'</label><select id="learnerAge"><option value="0">'+t('اختيار المستوى يدويًا','Choose level manually')+'</option>'+[4,5,6,7,8].map(function(age){return'<option value="'+age+'"'+(S.learner_age===age?' selected':'')+'>'+age+'</option>'}).join('')+'</select><p class="local-note">'+t('الأعمار إرشادية. كل المستويات متاحة، وتتطور المهام من الصور إلى الكلمات والجمل ثم التأليف.','Ages are guides. All levels stay open: pictures, words and sentences, then authorship.')+'</p></section><p class="muted">'+t('رافق المحاولة، ثم اختر خطوة واحدة مناسبة للاستعداد.','Support the try, then choose one next step that fits readiness.')+'</p><div class="coach-grid"><section class="panel"><h2>'+t('الاستعداد والدعم','Readiness & support')+'</h2>'+tracks()+'<label for="supportLevel">'+t('الدعم الافتراضي','Default support')+'</label><select id="supportLevel">'+['together','hint','independent'].map(function(v){return'<option value="'+v+'"'+(S.assistance===v?' selected':'')+'>'+supportName(v)+'</option>'}).join('')+'</select><div class="prompt-box">'+esc(s.coach_tip)+'</div><p>'+t('الأول: صور واستماع ونهاية بالضغط. الثاني: كلمة وجملة قصيرة. الثالث: كلمة جديدة وجملة أطول وحكاية حتى خمس صور. تغيير المستوى يحفظ حكاية الطفل المؤلفة.','First: pictures, listening and a picture ending. Second: a word and short sentence. Third: a new word, longer sentence and up to five pictures. Level changes preserve authored stories.')+'</p></section><section class="panel"><h2>'+t('قالبك دون تغيير الأصل','Your template; original preserved')+'</h2><label for="templateSource">'+t('الحكاية الأصلية','Original story')+'</label><select id="templateSource">';D.stories.filter(function(x){return x.language===S.language}).forEach(function(x){out+='<option value="'+x.id+'">'+esc(x.title)+'</option>'});out+='</select><label for="templateTitle">'+t('عنوان نسختك','Your template title')+'</label><input id="templateTitle" class="profile-input" maxlength="100"><label for="templateTip">'+t('تعليمة أو سؤال للمرافق','Coach instruction or question')+'</label><textarea id="templateTip" maxlength="500"></textarea>'+b('template-copy',t('احفظ القالب وافتحه','Save template & open it'),undefined,'primary')+'</section><section class="panel"><h2>'+t('ملاحظة وصفية خاصة','Private observation')+'</h2><p>'+esc(s.title)+'</p><p class="local-note">'+t('محلية لهذا المستخدم وخارج التصدير. دوّن المحاولة والمساعدة والخطوة القادمة دون تشخيص أو مقارنة.','Local to this profile, outside exports. Note the try, support and next step, without diagnosis or ranking.')+'</p><textarea id="coachNote" data-field="coach-note" maxlength="1000">'+esc(notes[s.id]||'')+'</textarea><ul class="muted">'+d.attempt_history.slice(-6).map(function(n){return'<li>'+esc(n.detail||n.action)+' · '+supportName(n.support)+'</li>'}).join('')+'</ul>'+b('clear-note',t('حذف الملاحظة','Delete note'),s.id,'small danger')+'</section></div>';if(corrupt)out+='<section class="panel"><h2>'+t('استعادة التخزين','Storage recovery')+'</h2><p>'+t('لن نكتب فوق الملف غير المقروء. احفظ نسخة خام قبل بدء حفظ جديد.','Unreadable data will not be overwritten. Back it up before starting a new save.')+'</p>'+b('raw-backup',t('تنزيل نسخة خام','Download raw backup'))+' '+b('reset-corrupt',t('ابدأ ملف حفظ جديد','Start a new save'),undefined,'danger')+'</section>';return out}


function sequence(ids,lang,i,follow){i=i||0;if(i>=ids.length)return;if(follow){draft().listen_index=i;save();render()}play(D.scenes[ids[i]].audio[lang],function(){sequence(ids,lang,i+1,follow)})}
function download(data,filename){try{var blob=new Blob([data],{type:'application/json;charset=utf-8'});if(navigator.msSaveBlob){navigator.msSaveBlob(blob,filename);return}var url=URL.createObjectURL(blob),a=doc.createElement('a');a.href=url;a.download=filename;doc.body.appendChild(a);a.click();a.parentNode.removeChild(a);setTimeout(function(){URL.revokeObjectURL(url)},1500)}catch(e){notify(t('التنزيل غير متاح هنا؛ استخدم متصفحًا أحدث للتصدير.','Downloads unavailable; use a newer browser to export.'))}}
function action(cmd,v){if(childAction(cmd,v))return;var d=story()?draft():null,wd=d?D.words[story().word]:null,parts,a,s,i;
if(cmd==='home'){save();stopAudio();stopRecord();try{if(w.parent!==w&&w.parent.APP360_FAMILY_SHELL){w.parent.APP360_FAMILY_SHELL.closeApp();return}}catch(e){}location.href='../../../index.html';return}
if(cmd==='language'){stopRecord();clearRecURL();S.language=v;S.active='';go('library');return}if(['library','saved','coach'].indexOf(cmd)>=0){stopRecord();go(cmd);return}if(cmd==='track'){S.track=v;if(d){d.readiness_track=v;d.practice_scenes=M.taskScenes(story(),v);d.scene_order=d.practice_scenes.slice().reverse();d.listen_index=0}save();render();return}if(cmd==='open'){openStory(v);return}if(cmd==='stage'){stopRecord();go(v);return}if(cmd==='stop-audio'){stopAudio();return}if(cmd==='play-scene'){play(D.scenes[v].audio[S.language]);return}if(cmd==='play-all'){sequence(d.practice_scenes,S.language,0,true);return}if(cmd==='listen-prev'||cmd==='listen-next'){stopAudio();d.listen_index=Math.max(0,Math.min(d.practice_scenes.length-1,d.listen_index+(cmd==='listen-next'?1:-1)));save();render();return}if(cmd==='show-text'){showText=!showText;render();return}
if(cmd==='order-move'||cmd==='compose-move'){parts=v.split(':');M.move(cmd==='order-move'?d.scene_order:d.compose,parts[0],parts[1]);M.note(d,cmd,v);save();render();return}if(cmd==='order-check'){var same=d.scene_order.join('|')===d.practice_scenes.join('|');M.note(d,'sequence-described',same?'original-order':'alternative-order');save();$('orderFeedback').innerHTML='<p class="success-text">'+(same?t('الترتيب يحكي الأحداث. احكِ: أولًا… ثم… وفي النهاية…','The pictures follow the events. Tell it: first… then… at the end…'):t('هذا ترتيبك الآن. احكِ ما تغير، أو جرّب ترتيبًا آخر.','This is your sequence. Tell what changed, or try another order.'))+'</p>';return}if(cmd==='order-hint'){play(D.scenes[d.practice_scenes[0]].audio[S.language]);notify(D.scenes[d.practice_scenes[0]].text[S.language]);return}if(cmd==='question'){play(story().question_audio);return}if(cmd==='meaning'){d.meaning_choice=Number(v);M.note(d,'meaning-explained',v);save();render();return}
if(cmd==='word-add'){i=Number(v);if(d.grapheme_sequence.indexOf(i)<0)d.grapheme_sequence.push(i);M.note(d,'sound-added',wd.units[i]);save();render();play(wd.unit_audio[i]);return}if(cmd==='word-remove'){d.grapheme_sequence.splice(Number(v),1);save();render();return}if(cmd==='word-reset'){d.grapheme_sequence=[];save();render();return}if(cmd==='word-model'){d.grapheme_sequence=wd.units.map(function(x,i){return i});save();render();play(wd.audio);return}if(cmd==='word-check'){var built=M.assembled(d,wd),matches=M.letters(built)===M.letters(wd.text);d.decoded_word=built;M.note(d,'blend-described',built);save();$('wordFeedback').innerHTML='<p class="success-text">'+(matches?t('ركبت الكلمة. اسمعها متصلة وابحث عن معناها في الحكاية.','You built the word. Hear it joined and find its meaning.'):t('استمع لكل مقطع وجرّب ترتيبًا آخر، أو شاهد الكلمة متصلة.','Hear each sound and try again, or see the joined word.'))+'</p>';if(matches)play(wd.audio);return}if(cmd==='word-play'){play(wd.audio);return}if(cmd==='phrase'){play(wd.phrase_audio);return}if(cmd==='transfer'){M.note(d,'new-word-explored',wd.transfer);save();play(wd.transfer_audio);notify(t('جرّب مع مرافقك: ','Try with your companion: ')+wd.transfer);return}
if(cmd==='compose-add'){if(d.compose.length<5)d.compose.push(v);M.note(d,'scene-added',v);save();render();return}if(cmd==='compose-remove'){if(d.compose.length>2)d.compose.splice(Number(v),1);save();render();return}if(cmd==='support'){d.assistance_level=v;M.note(d,'support-described',v);save();render();return}if(cmd==='save-story'){if(rec||recordSaving){notify(t('انتظر انتهاء حفظ التسجيل ثم احفظ الحكاية.','Wait for the recording to finish saving, then save the story.'));return}if(S.saved.length>=50){notify(t('الرف ممتلئ. صدّر نسخة واحذف حكاية عند الحاجة.','Shelf full. Export a copy, then remove a story if needed.'));return}M.note(d,'story-saved',d.title);d.status='saved';a=M.artifact(d,profile,D);S.saved.push(a);savedId=a.id;go('read-saved');notify(storageOK?t('حُفظت حكايتك على هذا الجهاز.','Story saved on this device.'):t('حفظ مؤقت؛ صدّرها قبل الإغلاق.','Temporary save; export before closing.'));return}
if(cmd==='read-saved'){a=findSaved(v);if(a){S.language=a.language;savedId=v;go('read-saved')}return}if(cmd==='copy-saved'){a=findSaved(v);if(!a)return;s=M.findStory(D,S,a.story_id)||D.stories.filter(function(x){return x.language===a.language})[0];S.active=s.id;S.language=a.language;d=M.ensureDraft(S,s);d.compose=a.scenes.slice();d.captions=M.copy(a.captions);d.title=a.title;d.ending=a.ending;d.reflection=a.reflection;d.recording_ref_optional='';clearRecURL();go('compose');return}if(cmd==='delete-saved'){if(w.confirm(t('حذف الحكاية من جهاز هذا المستخدم؟','Delete this story from this profile?'))){S.saved=S.saved.filter(function(a){return a.id!==v});save();render()}return}if(cmd==='print'){a=findSaved(v);if(a){$('printBook').innerHTML=book(a);w.print()}return}if(cmd==='listen-saved'){a=findSaved(v);if(a)sequence(a.scenes,a.language,0,false);return}if(cmd==='play-saved-recording'){a=findSaved(v);if(a)playRecording(a.recording_ref_optional);return}if(cmd==='export'){download(JSON.stringify(M.exportData(S.saved,D),null,2),'story-and-word-'+new Date().toISOString().slice(0,10)+'.json');return}
if(cmd==='template-copy'){if(!coachAllowed())return;if(S.custom.length>=20){notify(t('وصلت إلى 20 قالبًا خاصًا.','You already have 20 templates.'));return}s=M.copy(M.findStory(D,S,$('templateSource').value));s.source_id=s.id;s.id='custom-'+Date.now().toString(36);s.title=$('templateTitle').value.slice(0,100)||s.title;s.coach_tip=$('templateTip').value.slice(0,500)||s.coach_tip;S.custom.push(s);save();openStory(s.id);return}if(cmd==='clear-note'){if(coachAllowed()&&w.confirm(t('حذف هذه الملاحظة الخاصة؟','Delete this private note?'))){delete notes[v];save();render()}return}if(cmd==='raw-backup'){try{download(localStorage.getItem(key)||'','story-unreadable-backup.json')}catch(e){}return}if(cmd==='reset-corrupt'){if(coachAllowed()&&w.confirm(t('بدء حفظ جديد؟ احتفظ بالنسخة الخام أولًا.','Start a new save? Keep the raw backup first.'))){corrupt=false;save();render()}return}
if(cmd==='record-start'){startRecord();return}if(cmd==='record-stop'){stopRecord();return}if(cmd==='record-play'){playRecording(d.recording_ref_optional);return}if(cmd==='record-delete'){if(!w.confirm(t('حذف التسجيل المحلي؟','Delete this local recording?')))return;var ref=d.recording_ref_optional;d.recording_ref_optional='';clearRecURL();if(db&&ref)try{db.transaction('voices','readwrite').objectStore('voices').delete(ref)}catch(e){}save();render()}}
function onInput(e){var el=e.target,f=el.getAttribute&&el.getAttribute('data-field');if(!f)return;if(f==='coach-note'){if(!coachAllowed())return;var st=story()||D.stories.filter(function(x){return x.language===S.language})[0];notes[st.id]=el.value.slice(0,1000);save();return}if(!story())return;var d=draft();if(f==='ending')d.ending_choice=null;if(f==='caption')d.captions[el.getAttribute('data-scene')]=el.value.slice(0,500);else if(['title','ending','reflection'].indexOf(f)>=0)d[f]=el.value.slice(0,f==='title'?100:f==='ending'?1000:500);d.status='in_progress';save()}
function importFile(file){if(!file)return;if(file.size>500000){notify(t('الملف أكبر من الحد المسموح.','File too large.'));return}var requested=profile,r=new FileReader();r.onload=function(){if(requested!==profile){notify(t('تغير المستخدم؛ اختر الملف مجددًا.','Profile changed; choose the file again.'));return}try{var rows=M.importData(JSON.parse(r.result),D);if(rows.length+S.saved.length>50)throw Error('shelf-full');if(!w.confirm(t('استعادة '+rows.length+' حكاية لهذا المستخدم دون استبدال الموجود؟','Restore '+rows.length+' stories to this profile, keeping existing stories?')))return;rows.forEach(function(a,i){a.id='import-'+Date.now().toString(36)+'-'+i;a.profile_ref=profile;S.saved.push(a)});save();render();notify(t('استعيدت الحكايات دون الصوت أو الملاحظات الخاصة.','Stories restored without recordings or private notes.'))}catch(e){notify(t('ملف غير صالح أو يتجاوز سعة الرف.','Invalid file, or shelf capacity exceeded.'))}};r.onerror=function(){notify(t('تعذرت قراءة الملف.','File could not be read.'))};r.readAsText(file)}
function openDB(){db=null;if(!w.indexedDB)return;var p=profile;try{var r=indexedDB.open('app360-story-voice:'+encodeURIComponent(p),1);r.onupgradeneeded=function(e){e.target.result.createObjectStore('voices')};r.onsuccess=function(){if(p===profile)db=r.result;else r.result.close()};r.onerror=function(){db=null}}catch(e){}}
function clearRecURL(){if(recURL)stopAudio();if(recURL)URL.revokeObjectURL(recURL);recURL='';recRef=''}
function releaseStream(){clearTimeout(recTimer);if(stream&&stream.getTracks)stream.getTracks().forEach(function(track){track.stop()});stream=null}
function startRecord(){if(rec||recordSaving)return;if(!w.MediaRecorder||!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia){notify(t('التسجيل غير متاح؛ الحكي والكتابة يعملان بالكامل.','Recording unavailable; storytelling and writing work fully.'));return}stopAudio();var p=profile,id=S.active;navigator.mediaDevices.getUserMedia({audio:true}).then(function(s){if(p!==profile||id!==S.active||view!=='compose'){s.getTracks().forEach(function(x){x.stop()});return}var chunks=[],target=draft(),ref='voice-'+Date.now().toString(36);stream=s;try{var r=new MediaRecorder(s);rec=r;r.ondataavailable=function(e){if(e.data.size)chunks.push(e.data)};r.onerror=function(){releaseStream();rec=null;notify(t('توقف التسجيل؛ تابع دون تسجيل.','Recording stopped; continue without recording.'))};r.onstop=function(){releaseStream();rec=null;if(p!==profile||!chunks.length)return;var blob=new Blob(chunks,{type:r.mimeType||'audio/webm'});clearRecURL();recURL=URL.createObjectURL(blob);recRef=ref;if(db){try{recordSaving=true;var tx=db.transaction('voices','readwrite');tx.objectStore('voices').put(blob,ref);tx.oncomplete=function(){recordSaving=false;if(p!==profile)return;target.recording_ref_optional=ref;save();if(view==='compose')render();notify(t('حُفظ الصوت محليًا.','Voice saved locally.'))};tx.onabort=tx.onerror=function(){recordSaving=false;notify(t('الصوت متاح لهذه الجلسة فقط؛ تعذر حفظه.','Voice available this session only; storage failed.'))}}catch(e){recordSaving=false;notify(t('تعذر حفظ الصوت؛ متاح حتى الإغلاق فقط.','Voice could not be saved; available until closing.'))}}else notify(t('الصوت متاح حتى إغلاق الصفحة فقط.','Voice available only until the page closes.'));save();if(view==='compose')render()};r.start();recTimer=setTimeout(stopRecord,60000);render()}catch(e){releaseStream();rec=null;notify(t('تعذر التسجيل؛ تابع بالحكي أو الكتابة.','Recording failed; continue by telling or writing.'))}}).catch(function(){notify(t('لم يُسمح بالميكروفون. يمكنك إكمال الحكاية دون تسجيل.','Microphone not allowed. You can finish without recording.'))})}
function stopRecord(){if(rec&&rec.state!=='inactive')try{rec.stop()}catch(e){rec=null;releaseStream()}else releaseStream()}
function playRecording(ref){if(recURL&&(!ref||ref===recRef)){play(recURL);return}if(!ref||!db){notify(t('التسجيل غير متاح على هذا الجهاز.','Recording unavailable on this device.'));return}var p=profile;try{var r=db.transaction('voices').objectStore('voices').get(ref);r.onsuccess=function(){if(p!==profile)return;if(!r.result){notify(t('لم نجد التسجيل المحلي.','Local recording not found.'));return}clearRecURL();recURL=URL.createObjectURL(r.result);recRef=ref;play(recURL)}}catch(e){notify(t('تعذر فتح التسجيل.','Recording could not be opened.'))}}
function offlineLabel(){$('offlineStatus').textContent=offline?t('الحكايات والصوت جاهزان دون إنترنت','Stories & audio ready offline'):('serviceWorker'in navigator)?t('الحزمة المحلية قيد التجهيز أو غير مكتملة','Offline pack preparing or incomplete'):t('استخدم الاتصال؛ الكاش غير متاح هنا','Use a connection; offline caching unavailable here')}
function checkOffline(){if(!w.caches||!navigator.serviceWorker)return;try{caches.open('a4-story-language-preview-2').then(function(c){return c.match('./offline-ready.json')}).then(function(r){offline=!!r;offlineLabel()}).catch(function(){offline=false;offlineLabel()})}catch(e){}}
function level(track){return M.level(D,track||S.track)}
function flow(){return level(story()?draft().readiness_track:S.track).steps}
function trackName(v){var l=level(v);return l?l[S.language]:''}
function guidePath(id){var g=D.guides[id];return g?g[S.language].audio:''}
function guide(id,end){if(S.voice_guidance&&guidePath(id))play(guidePath(id),end);else if(end)end()}
function prime(){var paths=[],s=story(),d=s?draft():null,wd;if(view==='library'){paths=[guidePath('home'),guidePath(S.track)];D.stories.filter(function(x){return x.language===S.language&&x.track===S.track}).slice(0,2).forEach(function(x){paths.push(x.title_audio,D.scenes[x.scenes[0]].audio[S.language])})}else if(d){paths.push(guidePath(view));if(view==='listen'){d.practice_scenes.forEach(function(id){paths.push(D.scenes[id].audio[S.language])})}else if(view==='meaning')paths.push(s.question_audio,guidePath('retry'),guidePath('meaning-found'));else if(view==='word'){wd=M.wordFor(D,s,d);paths=paths.concat(wd.unit_audio,[wd.audio,guidePath('retry')])}else if(view==='sentence'){var se=s.sentences[d.readiness_track==='extend'?'extend':'practice'];paths=paths.concat(se.unit_audio,[se.audio,guidePath('retry')])}else if(view==='compose')s.endings.forEach(function(e){paths.push(e.audio)})}if(w.APP360_STORY_AUDIO)w.APP360_STORY_AUDIO.warm(paths.filter(function(x){return !!x}))}
function enterStage(p,spoken){go(p);if(spoken)guide(p,function(){if(view!==p)return;if(p==='listen')sequence(draft().practice_scenes,S.language,0,true);else if(p==='meaning')play(story().question_audio);else if(p==='word')play(M.wordFor(D,story(),draft()).audio);else if(p==='sentence')play(story().sentences[draft().readiness_track==='extend'?'extend':'practice'].audio)})}
function setLevel(v,spoken){if(['entry','practice','extend'].indexOf(v)<0)return;stopAudio();stopRecord();S.track=v;var d=story()?draft():null;if(d){d.readiness_track=v;d.practice_scenes=M.taskScenes(story(),v);d.scene_order=d.practice_scenes.slice().reverse();d.order_picks=[];d.listen_index=0;d.transfer_mode=false}S.active='';showAllStories=false;go('library');if(spoken)guide(v)}
function scene(id,lang,large){var s=D.scenes[id];if(!s)return '';var alt=esc(s.text[lang||S.language]),img='<img src="'+esc(s.fallback_sheet||s.sheet)+'" alt="'+alt+'" draggable="false" loading="'+(large?'eager':'lazy')+'" decoding="async">';if(s.small_sheet)img='<picture><source type="image/webp" srcset="'+esc(s.small_sheet)+' 640w, '+esc(s.sheet)+' 1024w" sizes="'+(large?'(max-width: 600px) 640px, 880px':'(max-width: 600px) 320px, 520px')+'">'+img+'</picture>';return'<div class="scene tile-'+s.tile+'">'+img+'</div>'}
function tracks(){return'<div class="tracks levels">'+D.levels.map(function(l){var count=S.progress[l.id].length;return b('track','<span class="level-number">'+l.number+'</span><span><strong>'+esc(l[S.language])+'</strong><small><span dir="ltr" class="age-range">'+l.age_min+'–'+l.age_max+'</span> '+t('سنوات · مقترح','years · suggested')+'</small></span><span class="level-symbol" aria-hidden="true">'+l.icon+'</span>',l.id,'track '+(S.track===l.id?'selected':'')+' '+l.id)}).join('')+'</div>'}
function library(){var rows=D.stories.concat(S.custom).filter(function(x){return x.language===S.language&&(showAllStories||x.track===S.track)}),first=rows[0],count=S.progress[S.track].length,l=level();var out='<section class="hero child-hero"><div class="hero-copy"><div class="eyebrow">'+t('مدرسة العائلة 360 · <span dir="ltr" class="age-range">4–8</span>','Family School 360 · 4–8')+'</div><h1>'+t('اسمع صورة…<br>واصنع حكاية!','Hear a picture.<br>Make a story!')+'</h1><p>'+t('اضغط صورة. سنمشي معًا خطوة خطوة.','Tap a picture. Take one small step at a time.')+'</p><div class="row">'+b('open',t('▶ ابدأ الحكاية','▶ Start a story'),first.id,'primary big-start')+b('guide',t('🔊 اسمع كيف نلعب','🔊 Hear how to play'),'home','small')+'</div></div><picture class="cover"><source type="image/webp" srcset="../../../assets/covers/a4-story-language-v2-320.webp 320w, ../../../assets/covers/a4-story-language-v2-640.webp 640w" sizes="(max-width:600px) 110px, 218px"><img src="../../../assets/covers/a4-story-language-v2-320.jpg" width="320" height="400" alt="'+t('حكاية وكلمة','Story & Word')+'" fetchpriority="high"></picture></section><h2 class="level-heading">'+t('اختر رحلتك','Choose your journey')+'</h2>'+tracks()+'<div class="level-summary"><span>'+t('المستوى','Level')+' '+l.number+' · '+esc(l[S.language])+'</span><span class="progress-books">'+t('حكايات صنعتها: ','Stories made: ')+count+'</span></div><section class="cards">';rows.forEach(function(s){out+='<article class="story-card"><button class="card-art scene-button" data-do="open" data-value="'+esc(s.id)+'" aria-label="'+t('ابدأ ','Start ')+esc(s.title)+'">'+scene(s.scenes[0])+'<span class="picture-play" aria-hidden="true">▶</span></button><div class="card-copy"><h3>'+esc(s.title)+'</h3><div class="card-buttons">'+b('open',t('▶ نلعب','▶ Play'),s.id,'primary')+b('story-title',s.source_id?t('🔊 مقدمة','🔊 Introduction'):t('🔊 الاسم','🔊 Title'),s.id,'small')+'</div></div></article>'});out+='</section><div class="row library-bottom">'+b('all-stories',showAllStories?t('حكايات هذا المستوى','This level’s stories'):t('حكايات أخرى','More stories'),undefined,'small')+b('saved',t('📖 حكاياتي','📖 My stories'),undefined,'small')+'</div><p class="local-note">'+t('الأعمار مقترحة. يمكنك تغيير المستوى والعودة إلى أي حكاية.','Ages are suggestions. You can change level and revisit any story.')+'</p>';if(count>=2&&S.track!=='extend')out+='<section class="next-level"><h3>'+t('هل نجرب رحلة جديدة؟','Try a new journey?')+'</h3>'+b('level-next',t('المستوى التالي ←','Next level →'),undefined,'primary')+'</section>';return out}
function stageHeader(){var f=flow(),ix=f.indexOf(view),labels={listen:t('أسمع','Listen'),order:t('أرتب','Order'),meaning:t('أكتشف','Discover'),word:t('كلمة','Word'),sentence:t('جملة','Sentence'),compose:t('حكايتي','My story'),review:t('أراجع','Reflect')};return'<div class="row spread story-header"><div><span class="eyebrow">'+t('المستوى','Level')+' '+level(draft().readiness_track).number+' · '+t('خطوة '+(ix+1)+' من '+f.length,'Step '+(ix+1)+' of '+f.length)+'</span><h1>'+esc(story().title)+'</h1></div>'+b('guide',t('🔊 اسمع المطلوب','🔊 Hear what to do'),view,'guide-button')+'</div><div class="row journey-caption"><strong>'+esc(labels[view]||'')+'</strong>'+b('toggle-steps',t('خطوات الحكاية','Story steps'),undefined,'small')+'</div><nav class="stage-nav" '+(showSteps?'':'hidden')+'>'+f.map(function(p,i){return b('stage','<span>'+ (i+1)+'</span> '+labels[p],p,view===p?'selected':'')}).join('')+'</nav>'}
function journeyActions(){var f=flow(),ix=f.indexOf(view);return'<div class="journey-actions">'+(ix>0?b('stage',t('السابق →','← Back'),f[ix-1],'small'):b('library',t('الحكايات →','← Stories'),undefined,'small'))+(ix<f.length-1?b('stage',t('التالي ←','Next →'),f[ix+1],'primary next-step'):b('save-story',t('✓ احفظ حكايتي','✓ Save my story'),undefined,'primary next-step'))+'</div>'}
function listen(){var d=draft(),sid=d.practice_scenes[d.listen_index];return'<section class="panel workspace"><div class="art-column"><button data-do="play-scene" data-value="'+sid+'" class="scene-button listening-picture" aria-label="'+t('اسمع المشهد','Hear this picture')+'">'+scene(sid,S.language,true)+'<span class="picture-play" aria-hidden="true">'+icon('sound')+'</span></button></div><div class="text-column"><div class="eyebrow">'+t('صورة '+(d.listen_index+1)+' من '+d.practice_scenes.length,'Picture '+(d.listen_index+1)+' of '+d.practice_scenes.length)+'</div><h2>'+t('اضغط الصورة… واسمعها','Tap the picture. Hear its story.')+'</h2><div class="row">'+b('play-all',t('▶ اسمع الحكاية','▶ Hear the story'),undefined,'primary')+b('stop-audio',t('■ إيقاف','■ Stop'),undefined,'small')+'</div><div class="reader-controls row">'+b('listen-prev',t('صورة سابقة →','← Previous picture'),undefined,'small',d.listen_index===0)+b('listen-next',t('صورة أخرى ←','Next picture →'),undefined,'small',d.listen_index===d.practice_scenes.length-1)+'</div><div class="prompt-box">'+t('ماذا ترى؟ يمكنك الحكي أو الإشارة.','What can you see? Tell it or point.')+'</div>'+b('show-text',showText?t('أخفي الجملة','Hide the sentence'):t('أرى الجملة','See the sentence'),undefined,'small')+(showText?'<p class="scene-text">'+esc(D.scenes[sid].text[S.language])+'</p>':'')+'</div></section>'}
function order(){var d=draft(),picks=d.order_picks||[],out='<section class="panel"><h2>'+t('أين البداية؟','Where does it begin?')+'</h2><p>'+t('اضغط الصور بالترتيب الذي تختاره.','Tap the pictures in the order you choose.')+'</p><div class="order-slots">';d.practice_scenes.forEach(function(id,i){out+=picks[i]?b('order-return','<span class="number">'+(i+1)+'</span>'+scene(picks[i]),i,'order-slot filled'): '<div class="order-slot empty-slot"><span>'+ (i+1)+'</span><small>'+t('صورة هنا','Picture here')+'</small></div>'});out+='</div><div class="order-bank">';d.practice_scenes.slice().reverse().forEach(function(id){out+=b('order-pick',scene(id),id,'picture-choice',picks.indexOf(id)>=0)});return out+'</div><div class="row">'+b('order-check',t('▶ اسمع ترتيبي','▶ Hear my sequence'),undefined,'primary',picks.length!==d.practice_scenes.length)+b('order-clear',t('أجرب ترتيبًا آخر','Try another order'),undefined,'small')+b('order-hint',t('🔊 ساعدني بالبداية','🔊 Help me begin'),undefined,'small')+'</div><div id="orderFeedback" role="status"></div></section>'}
function meaning(){var s=story(),d=draft();return'<section class="panel"><div class="row spread"><h2>'+esc(s.question)+'</h2>'+b('question',t('🔊 اسمع السؤال','🔊 Hear the question'),undefined,'primary')+'</div><div class="choices">'+s.choices.map(function(c,i){return b('meaning',scene(c.scene)+'<span>'+esc(c.label)+'</span>',i,'choice '+(d.meaning_choice===i?'selected':''))}).join('')+'</div>'+(d.meaning_choice!==null?'<p class="success-text">'+(d.meaning_choice===s.meaning?t('وجدت الصورة. ماذا لاحظت؟','You found the picture. What did you notice?'):t('لنسمع ونلاحظ مرة أخرى.','Let’s listen and look again.'))+'</p>':'')+'</section>'}
function word(){var d=draft(),wd=M.wordFor(D,story(),d),seq=d.transfer_mode?d.transfer_graphemes:d.grapheme_sequence;var out='<section class="panel"><h2>'+t('أسمع الأصوات… وأبني كلمة','Hear the sounds. Build a word.')+'</h2><div class="word-area">'+(!d.transfer_mode?'<img class="word-picture" src="'+esc(wd.image)+'" alt="'+esc(wd.text)+'">':'<span class="tag">'+t('✦ كلمة جديدة','✦ A new word')+'</span>')+b('word-play',t('🔊 اسمع الكلمة','🔊 Hear the word'),undefined,'primary')+'<div class="word-display" id="builtWord">'+esc(M.assembled({grapheme_sequence:seq},wd)||'…')+'</div><div class="tiles">'+seq.map(function(n,i){return b('word-remove',esc(wd.units[n]),i,'placed')}).join('')+'</div><p class="muted">'+t('اضغط صوتًا لتسمعه وتضيفه.','Tap a sound to hear and add it.')+'</p><div class="tiles">';for(var i=wd.units.length-1;i>=0;i--)out+=b('word-add',esc(wd.units[i]),i,'tile',seq.indexOf(i)>=0);out+='</div><div class="row centered">'+b('word-check',t('▶ أمزج الكلمة','▶ Blend the word'),undefined,'primary')+b('word-reset',t('أحاول ثانية','Try again'),undefined,'small')+b('word-model',t('🔊 ساعدني','🔊 Help me'),undefined,'small')+'</div><div id="wordFeedback" role="status"></div></div>';if(!d.transfer_mode)out+='<p class="word-phrase">'+esc(wd.phrase)+'</p><div class="row centered">'+b('phrase',t('🔊 اسمع العبارة','🔊 Hear the phrase'))+'</div>';if(d.readiness_track==='extend')out+='<div class="transfer-card">'+b('transfer-build',d.transfer_mode?t('أعود إلى كلمة الحكاية','Back to the story word'):t('✦ أركّب كلمة جديدة','✦ Build a new word'),undefined,'coral')+'</div>';return out+'</section>'}
function sentence(){var d=draft(),track=d.readiness_track==='extend'?'extend':'practice',se=story().sentences[track],seq=d.sentence_sequences[track];var out='<section class="panel sentence-workshop"><div class="row spread"><h2>'+t('كلمة وكلمة… جملة!','Word by word. A sentence!')+'</h2>'+b('sentence-play',t('🔊 اسمع الجملة','🔊 Hear the sentence'),undefined,'primary')+'</div><div class="sentence-picture">'+scene(se.scene,S.language,true)+'</div><div class="sentence-built" id="builtSentence" dir="'+(S.language==='ar'?'rtl':'ltr')+'">';if(!seq.length)out+='<span class="muted">'+t('كلماتك ستظهر هنا','Your words will appear here')+'</span>';seq.forEach(function(n,i){out+=b('sentence-remove',esc(se.units[n]),i,'placed word-token')});out+='</div><div class="tiles sentence-bank">';for(var i=se.units.length-1;i>=0;i--)out+=b('sentence-add',esc(se.units[i]),i,'tile word-token',seq.indexOf(i)>=0);return out+'</div><div class="row centered">'+b('sentence-check',t('▶ اسمع ما ركّبت','▶ Hear what I built'),undefined,'primary')+b('sentence-clear',t('أجرب ثانية','Try again'),undefined,'small')+b('sentence-model',t('🔊 ساعدني بالجملة','🔊 Help me build it'),undefined,'small')+'</div><div id="sentenceFeedback" role="status"></div></section>'}
function compose(){var d=draft(),s=story(),max=level(d.readiness_track).compose_max;var out='<section class="panel"><h2>'+t('اختر نهاية لحكايتك','Choose your story’s ending')+'</h2><div class="ending-choices">'+s.endings.map(function(e,i){return b('ending-choice',scene(e.scene)+'<span>🔊 '+esc(e.text)+'</span>',i,'choice '+(d.ending_choice===i?'selected':''))}).join('')+'</div><h3>'+t('هذه حكايتك الآن','Your story now')+'</h3>'+cards(d.compose,'compose')+'<div class="row">'+b('compose-add',t('＋ صورة للنهاية','＋ An ending picture'),s.optional_scene,'',d.compose.length>=max)+(d.readiness_track==='extend'?b('compose-add',t('✦ صورة من حكاية أخرى','✦ A picture from another story'),s.scenes.indexOf('ball-2')>=0?'cup-3':'ball-2','small',d.compose.length>=max):'')+'</div>'+b('toggle-writing',showWriting?t('أخفي الكتابة','Hide writing'):t('✎ أضيف كتابة · اختياري','✎ Add writing · optional'),undefined,'small writing-toggle')+'<section class="writing-options" '+(showWriting?'':'hidden')+'><label for="storyTitle">'+t('عنوان حكايتك','Your story title')+'</label><input id="storyTitle" data-field="title" class="profile-input" maxlength="100" value="'+esc(d.title)+'"><label for="ending">'+t('نهاية من كلامك','An ending in your own words')+'</label><textarea id="ending" data-field="ending" maxlength="1000">'+esc(d.ending)+'</textarea></section>'+recordPanel()+'<div class="row">'+b('save-story',t('✓ احفظ حكايتي','✓ Save my story'),undefined,'primary big-start')+'</div></section>';return out}
function cards(ids,mode){return'<div class="timeline">'+ids.map(function(id,i){return'<div class="scene-card"><span class="number">'+(i+1)+'</span>'+scene(id)+'<div class="row">'+b(mode+'-move',t('← قبل','← Earlier'),i+':-1','small',i===0)+b(mode+'-move',t('بعد →','Later →'),i+':1','small',i===ids.length-1)+(mode==='compose'?b('compose-remove',t('− حذف','− Remove'),i,'small',ids.length<=2):'')+'</div>'+(mode==='compose'&&showWriting?'<label class="muted" for="caption-'+i+'">'+t('تعليق اختياري','Optional caption')+'</label><textarea id="caption-'+i+'" data-field="caption" data-scene="'+id+'" maxlength="500">'+esc(draft().captions[id]||'')+'</textarea>':'')+'</div>'}).join('')+'</div>'}
function review(){var d=draft();return'<section class="panel"><h2>'+t('ما الذي أحببته اليوم؟','What did you enjoy today?')+'</h2><div class="reflection-choices">'+[[t('🔊 الاستماع','🔊 Listening')],[t('▦ التركيب','▦ Building')],[t('📖 التأليف','📖 Creating')]].map(function(x){return b('reflect-pick',x[0],x[0],d.reflection===x[0]?'selected':'')}).join('')+'</div><p class="prompt-box">'+esc(story().real_world)+'</p><label for="reflection">'+t('أحكي أو أكتب · اختياري','Tell it or write it · optional')+'</label><textarea id="reflection" data-field="reflection" maxlength="500">'+esc(d.reflection)+'</textarea>'+b('save-story',t('✓ احفظ الحكاية','✓ Save story'),undefined,'primary')+'</section>'}
function render(){doc.documentElement.lang=S.language;doc.documentElement.dir=S.language==='ar'?'rtl':'ltr';$('brandTitle').textContent=t('حكاية وكلمة','Story & Word');$('profileLabel').textContent=name()+' · '+t('مدرسة العائلة 360','Family School 360');$('langAr').className=S.language==='ar'?'selected':'';$('langEn').className=S.language==='en'?'selected':'';$('navLibrary').textContent=t('الحكايات','Stories');$('navSaved').textContent=t('حكاياتي','My stories');$('navCoach').textContent=t('للمرافق','For the coach');$('voiceBtn').innerHTML=icon('sound',!S.voice_guidance);$('voiceBtn').setAttribute('aria-pressed',S.voice_guidance?'true':'false');$('voiceBtn').setAttribute('aria-label',S.voice_guidance?t('إيقاف الشرح التلقائي بالصوت','Turn off spoken guidance'):t('تشغيل الشرح التلقائي بالصوت','Turn on spoken guidance'));$('releaseBadge').textContent=t('نسخة تجريبية','Preview');var html;if(view==='library')html=library();else if(view==='saved')html=savedLibrary();else if(view==='read-saved')html=readSaved();else if(view==='coach')html=coach();else if(story())html=stageHeader()+({listen:listen,order:order,meaning:meaning,word:word,sentence:sentence,compose:compose,review:review}[view]||listen)()+journeyActions();else{view='library';html=library()}$('app').innerHTML=html;storageLabel();offlineLabel();$('footerNote').textContent=t('على مهلك… اسمع وجرّب واصنع حكايتك.','Take your time. Listen, try, and make your story.');prime()}
function play(path,end){stopAudio();var n=token;if(w.APP360_STORY_AUDIO){w.APP360_STORY_AUDIO.play(path,function(){if(n===token&&end)end()},function(){if(n===token)notify(t('اضغط الصوت مجددًا أو تابع بالصور.','Tap audio again, or continue with pictures.'))});return}audio.src=path;audio.onended=function(){if(n===token&&end)end()};try{var p=audio.play();if(p&&p.catch)p.catch(function(){if(n===token)notify(t('اضغط الصوت مجددًا.','Tap audio again.'))})}catch(e){notify(t('تابع بالصور الآن.','Continue with pictures for now.'))}}
function openStory(id,stage){var s=M.findStory(D,S,id);if(!s)return;stopRecord();clearRecURL();S.active=id;S.language=s.language;var d=M.ensureDraft(S,s);if((stage==='word'||stage==='sentence')&&S.track==='entry')S.track='practice';if(d.readiness_track!==S.track){d.readiness_track=S.track;d.practice_scenes=M.taskScenes(s,S.track);d.scene_order=d.practice_scenes.slice().reverse();d.order_picks=[];d.listen_index=0}d.status='in_progress';d.assistance_level=S.assistance;showWriting=false;showSteps=false;M.note(d,'opened',stage||'listen');enterStage(stage||'listen',true)}
function childAction(cmd,v){var d=story()?draft():null,s=story(),i,seq,wd,se,track,a;if(cmd==='voice'){S.voice_guidance=!S.voice_guidance;save();render();if(S.voice_guidance)guide(view==='library'?'home':view);else stopAudio();return true}if(cmd==='guide'){play(guidePath(v));return true}if(cmd==='track'){setLevel(v,true);return true}if(cmd==='level-next'){i=['entry','practice','extend'].indexOf(S.track);setLevel(['entry','practice','extend'][Math.min(2,i+1)],true);return true}if(cmd==='all-stories'){showAllStories=!showAllStories;render();return true}if(cmd==='toggle-steps'){showSteps=!showSteps;render();return true}if(cmd==='toggle-writing'){showWriting=!showWriting;render();return true}if(cmd==='story-title'){a=M.findStory(D,S,v);if(a)play(a.title_audio);return true}if(cmd==='stage'){stopRecord();enterStage(v,true);return true}if(cmd==='listen-prev'||cmd==='listen-next'){stopAudio();d.listen_index=Math.max(0,Math.min(d.practice_scenes.length-1,d.listen_index+(cmd==='listen-next'?1:-1)));save();render();play(D.scenes[d.practice_scenes[d.listen_index]].audio[S.language]);return true}
if(cmd==='order-pick'){if(d.order_picks.indexOf(v)<0&&d.order_picks.length<d.practice_scenes.length)d.order_picks.push(v);if(d.order_picks.length===d.practice_scenes.length)d.scene_order=d.order_picks.slice();M.note(d,'picture-placed',v);save();render();play(D.scenes[v].audio[S.language]);return true}if(cmd==='order-return'){d.order_picks.splice(Number(v),1);save();render();return true}if(cmd==='order-clear'){d.order_picks=[];save();render();return true}if(cmd==='order-check'){if(d.order_picks.length!==d.practice_scenes.length)return true;d.scene_order=d.order_picks.slice();M.note(d,'sequence-described',d.scene_order.join('|'));save();$('orderFeedback').innerHTML='<p class="success-text">'+t('هذا ترتيبك. اسمع ما يحكيه.','This is your sequence. Hear the story it tells.')+'</p>';sequence(d.scene_order,S.language,0,false);return true}
if(cmd==='meaning'){d.meaning_choice=Number(v);M.note(d,'meaning-explained',v);save();render();guide(d.meaning_choice===s.meaning?'meaning-found':'retry');return true}if(cmd==='transfer-build'){d.transfer_mode=!d.transfer_mode;save();render();play(M.wordFor(D,s,d).audio);return true}
if(cmd.indexOf('word-')===0&&d){wd=M.wordFor(D,s,d);seq=d.transfer_mode?d.transfer_graphemes:d.grapheme_sequence;if(cmd==='word-add'){i=Number(v);if(seq.indexOf(i)<0)seq.push(i);M.note(d,'sound-added',wd.units[i]);save();render();play(wd.unit_audio[i],function(){if(M.letters(M.assembled({grapheme_sequence:seq},wd))===M.letters(wd.text))play(wd.audio)});return true}if(cmd==='word-remove'){seq.splice(Number(v),1);save();render();return true}if(cmd==='word-reset'){seq.splice(0,seq.length);save();render();return true}if(cmd==='word-model'){seq.splice(0,seq.length);wd.units.forEach(function(x,i){seq.push(i)});save();render();play(wd.audio);return true}if(cmd==='word-play'){play(wd.audio);return true}if(cmd==='word-check'){var built=M.assembled({grapheme_sequence:seq},wd),matches=M.letters(built)===M.letters(wd.text);d.decoded_word=built;M.note(d,'blend-described',built);save();$('wordFeedback').innerHTML='<p class="success-text">'+(matches?t('الكلمة متصلة. اسمعها!','Your word is joined. Hear it!'):t('اسمع الأصوات وجرب ترتيبًا آخر.','Hear the sounds and try another order.'))+'</p>';if(matches)play(wd.audio);else guide('retry');return true}}
if(cmd.indexOf('sentence-')===0&&d){track=d.readiness_track==='extend'?'extend':'practice';se=s.sentences[track];seq=d.sentence_sequences[track];if(cmd==='sentence-add'){i=Number(v);if(seq.indexOf(i)<0)seq.push(i);M.note(d,'sentence-word-added',se.units[i]);save();render();play(se.unit_audio[i]);return true}if(cmd==='sentence-remove'){seq.splice(Number(v),1);save();render();return true}if(cmd==='sentence-clear'){seq.splice(0,seq.length);save();render();return true}if(cmd==='sentence-model'){seq.splice(0,seq.length);se.units.forEach(function(x,i){seq.push(i)});save();render();play(se.audio);return true}if(cmd==='sentence-play'){play(se.audio);return true}if(cmd==='sentence-check'){var correct=seq.length===se.units.length&&seq.every(function(n,i){return n===i});M.note(d,'sentence-described',M.sentenceText(d,s));save();$('sentenceFeedback').innerHTML='<p class="success-text">'+(correct?t('جملتك تحكي الصورة. اسمعها!','Your sentence tells the picture. Hear it!'):t('هذا ترتيبك الآن. اسمع الكلمات أو جرّب ترتيبًا آخر.','This is your order. Hear the words, or try another order.'))+'</p>';if(correct)play(se.audio);else if(seq.length){var j=0;var hear=function(){if(j<seq.length)play(se.unit_audio[seq[j++]],hear)};hear()}else guide('sentence');return true}}
if(cmd==='ending-choice'){i=Number(v);a=s.endings[i];if(!a)return true;d.ending=a.text;d.ending_choice=i;var max=level(d.readiness_track).compose_max;if(d.compose.indexOf(a.scene)<0){if(d.compose.length<max)d.compose.push(a.scene);else d.compose[d.compose.length-1]=a.scene}M.note(d,'picture-ending-chosen',a.scene);save();render();play(a.audio);return true}if(cmd==='compose-add'){if(d.compose.length<level(d.readiness_track).compose_max)d.compose.push(v);M.note(d,'scene-added',v);save();render();play(D.scenes[v].audio[S.language]);return true}if(cmd==='reflect-pick'){d.reflection=v;M.note(d,'reflection-picked',v);save();render();return true}
if(cmd==='save-story'){if(rec||recordSaving){notify(t('انتظر حفظ التسجيل ثم احفظ الحكاية.','Wait for the voice to save, then save the story.'));return true}if(S.saved.length>=50){notify(t('الرف ممتلئ. صدّر نسخة من مكتب الحكايات.','The shelf is full. Export a copy from My stories.'));return true}M.note(d,'story-saved',d.title);d.status='saved';a=M.artifact(d,profile,D);a.sentence_text=M.sentenceText(d,s);S.saved.push(a);if(S.progress[d.readiness_track].indexOf(s.id)<0)S.progress[d.readiness_track].push(s.id);savedId=a.id;go('read-saved');guide('saved');return true}return false}

w.APP360_PWA_APPLY_PENDING=function(){if(!pendingReload)return false;if(rec||recordSaving){notify(t('أنهِ التسجيل أولًا.','Finish recording first.'));return true}save();stopAudio();var reload=pendingReload;pendingReload=null;reload();return true};
w.APP360_PWA_BEFORE_RELOAD=function(reload){if(!ownWorkerAtBoot){ownWorkerAtBoot=true;return}if(view==='library'&&!rec&&!recordSaving){reload();return}pendingReload=reload;$('updateAppBtn').textContent=t('تحديث جاهز','Update ready')};
load(identity());if(w.APP360_STORY_AUDIO)w.APP360_STORY_AUDIO.onState(function(state){$('audioState').textContent=state==='waiting'?t('الصوت قادم…','Sound loading…'):state==='playing'?t('أستمع الآن','Listening now'):''});doc.addEventListener('click',function(e){if(w.APP360_STORY_AUDIO)w.APP360_STORY_AUDIO.unlock();var n=e.target;while(n&&n!==doc){if(n.getAttribute&&n.getAttribute('data-do')){if(!n.disabled)action(n.getAttribute('data-do'),n.getAttribute('data-value'));break}n=n.parentNode}},false);doc.addEventListener('input',onInput,false);doc.addEventListener('change',function(e){onInput(e);if(e.target.id==='learnerAge'&&coachAllowed()){S.learner_age=Number(e.target.value)||0;if(S.learner_age){setLevel(M.levelForAge(S.learner_age),true)}else save()}if(e.target.id==='importFile')importFile(e.target.files[0]);if(e.target.id==='supportLevel'&&coachAllowed()){S.assistance=e.target.value;if(story())draft().assistance_level=S.assistance;save()}},false);w.addEventListener('beforeunload',function(){save();stopRecord()},false);w.addEventListener('pagehide',function(){save();stopRecord()},false);w.addEventListener('resize',save,false);doc.addEventListener('visibilitychange',function(){if(doc.hidden){save();stopAudio();stopRecord()}},false);w.addEventListener('popstate',function(){save();go(flow().indexOf(view)>0?flow()[flow().indexOf(view)-1]:'library')},false);setInterval(function(){var p=identity();if(p!==profile){save();stopAudio();stopRecord();clearRecURL();if(db)db.close();load(p)}else if(view==='coach'&&!coachAllowed())render();checkOffline()},1800);setTimeout(checkOffline,1000);
w.APP360_STORY={version:'preview-2',snapshot:function(){return M.copy(S)},profile:function(){return profile},open:openStory,exportData:function(){return M.exportData(S.saved,D)},isOfflineReady:function(){return offline}};
})(window,document);
